# Check biases for more conv3 channels
conv3_b = W['conv3.bias'].detach().cpu().numpy()
for ch in [3, 20, 31, 34, 37, 40, 46, 47, 62, 63]:
    print(f"conv3 channel {ch}: bias={conv3_b[ch]:.4f}")

# Also check fc.weight for class 8 and 4 in detail
fc_w = W['fc.weight'].detach().cpu().numpy()
print("\nClass 8 (ship) fc.weights for all channels:")
for ch in range(64):
    if fc_w[8, ch] > 0.2:
        print(f"  Channel {ch}: weight={fc_w[8, ch]:.4f}, bias={conv3_b[ch]:.4f}")

print("\nClass 4 (deer) fc.weights for all channels:")
for ch in range(64):
    if fc_w[4, ch] > 0.2:
        print(f"  Channel {ch}: weight={fc_w[4, ch]:.4f}, bias={conv3_b[ch]:.4f}")

print("\nClass 0 (airplane) fc.weights for all channels:")
for ch in range(64):
    if fc_w[0, ch] > 0.2:
        print(f"  Channel {ch}: weight={fc_w[0, ch]:.4f}, bias={conv3_b[ch]:.4f}")
